// Regenerates docs/TOOLS.md from the registry. Run: npm run docs:tools
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { format, resolveConfig } from 'prettier';
import { createServer } from 'vite';

const vite = await createServer({
  server: { middlewareMode: true },
  appType: 'custom',
  logLevel: 'silent',
});
const { TOOLS } = await vite.ssrLoadModule('/src/core/registry.ts');
const { CATEGORIES } = await vite.ssrLoadModule('/src/core/types.ts');
await vite.close();

const lines = [
  '# Tools',
  '',
  '<!-- Generated by `npm run docs:tools` from the tool registry. Do not edit by hand. -->',
  '',
  `${TOOLS.length} tools. Every one runs in the browser; each has "Try" examples on its page.`,
  '',
];
for (const cat of CATEGORIES) {
  const tools = TOOLS.filter((t) => t.category === cat.id);
  if (!tools.length) continue;
  lines.push(
    `## ${cat.name}`,
    '',
    '| Tool | What it does | Also known as |',
    '| --- | --- | --- |',
  );
  for (const t of tools) {
    const tags = (t.tags ?? []).slice(0, 6).join(', ');
    lines.push(
      `| **${t.name}** (\`${t.id}\`) | ${t.description.replace(/\|/g, '\\|')} | ${tags} |`,
    );
  }
  lines.push('');
}
// Formatted like the rest of the repo, so `npm run format:check` and the CI diff agree.
const out = fileURLToPath(new URL('../docs/TOOLS.md', import.meta.url));
const options = { ...(await resolveConfig(out)), filepath: out };
writeFileSync(out, await format(lines.join('\n'), options));
console.log(`docs/TOOLS.md: ${TOOLS.length} tools`);
